// Decide onde a conversa mora. O servidor lê apenas `{ tier }`.
//
//   1 — nada é gravado
//   2 — Redis com TTL (curto prazo)
//   3 — MongoDB (permanente)
//
// Heurística de propósito: isto roda uma vez por conversa nova, dentro de um
// timeout de 10s no servidor. Determinístico, sem custo e sem credencial —
// troque por um nó de LLM quando a classificação precisar de nuance.

const text = String($input.first().json.body?.text ?? '').toLowerCase().trim()

// Pedido explícito de lembrar algo além da sessão.
//
// Palavras soltas levam \b; frases, não. `\b` depois de `é` nunca casa —
// acentuada não é caractere de palavra em regex JS, então não existe fronteira
// entre `é` e o espaço, e "meu nome é Jonathan" escapava para o nível 2.
const durable = /\b(lembre|lembra|lembrar|anote|anota|guarde|guarda|memorize|prefiro)\b|meu nome é|me chamo|sempre que|de agora em diante|daqui em diante|nunca mais/

// Saudação ou agradecimento solto: não há contexto que valha guardar.
const throwaway = /^(oi|olá|ola|e aí|bom dia|boa tarde|boa noite|teste|testando|obrigado|obrigada|valeu|tchau)\b[\s!.?]*$/

const tier = durable.test(text) ? 3 : throwaway.test(text) ? 1 : 2

return [{ json: { tier } }]
